for path in files:
    if path.suffix != '.tex':
        continue
    for old, new in context.items():
        texts[path] = texts[path].replace(old, new)
    texts[path] = texts[path].replace('activated-sludge', 'activated sludge').replace('wastewater-treatment', 'wastewater treatment').replace('machine-learning', 'machine learning')
    texts[path] = texts[path].replace('raw-head', 'raw-regression').replace('raw head', 'raw regression').replace('raw-head', 'raw-regression')

replace('references.bib', 'author = {RIVAS, A and IRIZAR, I and AYESA, E}', 'author = {Rivas, A. and Irizar, I. and Ayesa, E.}')
replace('manuscript.tex', '    \\sc\\large\n    \\noindent \\thesisYear', '    \\large\n    \\noindent \\thesisYear')
paragraph('manuscript.tex', 'Activated sludge treatment links biological conversion,', r'''Activated sludge treatment uses suspended microorganisms to transform pollutants and retains biomass through solids separation and recirculation. Mechanistic models calculate the resulting concentrations from reaction and flow equations. Repeated simulation can be costly when many operating settings are examined. Statistical surrogates are fitted models that approximate these responses with faster evaluation. A small average prediction error can still conceal a mass conservation violation or a negative concentration. This research develops a common framework for prediction, physical enforcement, interpretation, and operating assessment. A steady-state reactor benchmark compares statistical models using different amounts of training data, separate model-selection and assessment partitions, and inputs beyond the training ranges. Projection adjusts each completed prediction to impose mass conservation and non-negative concentrations. Paired assessment distinguishes its effect on prediction error from the size of the adjustment. A structured second-order regression separates operating terms, influent terms, curvature, and fitted dependence among component concentrations. Its prediction procedure distinguishes physical guidance during fitting from constraints imposed on the final state. A connected plant surrogate extends enforcement to the mixer, reactor train, clarifier outlets, and stored solids. Selected operating controls are assessed through independent mechanistic calculations and comparison with direct optimization under common treatment and resource priorities. Predictive accuracy, satisfaction of imposed physical constraints, interpretability, and decision quality remain separate assessment requirements. Physical guarantees apply to the adopted process model and imposed constraints. Treatment outcomes and model performance require empirical assessment.''')

for path, text in texts.items():
    original = path.read_bytes().decode('utf-8').replace('\r\n', '\n')
    if text != original:
        path.write_bytes(text.replace('\n', newlines[path]).encode('utf-8'))
        print(path.relative_to(ROOT))
